input:
cd /hutian/repo; cat >> prior_work.bib <<'EOF'
@article{thiyageswaran2024data, author={Thiyageswaran, Vydhourie and McCormick, Tyler and Brennan, Jennifer}, title={Data-adaptive exposure thresholds for the {H}orvitz-{T}hompson estimator of the average treatment effect in experiments with network interference}, year={2024}, note={arXiv:2405.15887}}
@article{shirani2024causal, author={Shirani Faradonbeh, Mohamad Sadegh and Bayati, Mohsen}, title={Causal message-passing for experiments with unknown and general network interference}, journal={Proceedings of the National Academy of Sciences}, year={2024}, doi={10.1073/pnas.2322232121}}
@article{crump2009dealing, author={Crump, Richard K. and Hotz, V. Joseph and Imbens, Guido W. and Mitnik, Oscar A.}, title={Dealing with limited overlap in estimation of average treatment effects}, journal={Biometrika}, year={2009}, doi={10.1093/biomet/asn055}}
@article{damour2021overlap, author={D'Amour, Alexander and Ding, Peng and Feller, Avi and Lei, Lihua and Sekhon, Jasjeet}, title={Overlap in observational studies with high-dimensional covariates}, journal={Journal of Econometrics}, year={2021}, doi={10.1016/j.jeconom.2019.10.014}}
EOF
python3 - <<'EOF'
p='prior_work.md'
s=open(p).read()
s=s.replace("""- **Gao & Ding 2023**""","""- What the full texts of Chin 2019, Han–Ugander 2023 and Gao–Ding 2023 say (read 2026-11-25 by keyword and section, not in full): Chin (Fig. 2) already shows that the treated-neighbour fraction/count distributions under one observed Bernoulli(0.5) draw differ from those under global treatment/control, draws the off-policy-evaluation analogy, requires an exogeneity (correct-response-model) assumption, and says extrapolation "may not be too unreasonable" if the response is low-dimensional — qualitative, no scaling in degree/p/design. Han–Ugander note that the variance of sample means of the features may not scale as 1/n and give bias/RMSE tables over feature sets. Gao–Ding assume overlap of exposure probabilities and study regression estimators of exposure-mapping estimands (not GATE extrapolation). So the extrapolation viewpoint is not new; the quantified account, its decomposition, the design interaction and the diagnostic are the claimed additions, "to our knowledge within the literature checked".
- **Gao & Ding 2023**""")
s=s.replace("## What the study takes","""- Regression-style competitors found by the idea review: `thiyageswaran2024data` (data-adaptive exposure thresholds for HT; abstract read), `shirani2024causal` (causal message-passing; abstract read). Both enter the comparison (tiers below in the Brief).
- Adjacent ideas the extrapolation framing transfers from: limited overlap/positivity (`crump2009dealing`, `damour2021overlap`) and OLS prediction leverage at a far point. Exposure features here are functions of one shared assignment vector, so degree and design shape the leverage; that structure is what is new.

## What the study takes""")
open(p,'w').write(s)
EOF
git add -A; git commit -qm "Add competitors and overlap literature; record what the core regression papers already say"; git push -q origin main; echo ok
